import{_ as t,o as s,c as a,ao as i}from"./chunks/framework.DOMnz-Zz.js";const n="/ship-of-tools/dev/assets/architecture.Dj_pbUec.svg",g=JSON.parse('{"title":"Architecture at a Glance","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":null}'),o={name:"guide/architecture.md"};function r(l,e,h,d,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="Architecture-at-a-Glance" tabindex="-1">Architecture at a Glance <a class="header-anchor" href="#Architecture-at-a-Glance" aria-label="Permalink to &quot;Architecture at a Glance {#Architecture-at-a-Glance}&quot;">​</a></h1><p>Ship of Tools is <strong>three processes plus your REPL</strong>, talking over a socket — even when everything runs on one machine. This page covers what each process owns, why the split falls where it does, the one serialization seam between Rust and Julia, and how the same architecture runs a remote project with almost no extra plumbing.</p><h2 id="The-processes" tabindex="-1">The processes <a class="header-anchor" href="#The-processes" aria-label="Permalink to &quot;The processes {#The-processes}&quot;">​</a></h2><p><img src="'+n+`" alt=""></p><table tabindex="0"><thead><tr><th style="text-align:right;">Process</th><th style="text-align:right;">Language</th><th style="text-align:right;">Owns</th></tr></thead><tbody><tr><td style="text-align:right;">Frontend</td><td style="text-align:right;">Rust (winit + wgpu)</td><td style="text-align:right;">the native window, chrome, preview rendering, keystrokes. Stateless about the project — it renders what the backend sends and forwards input.</td></tr><tr><td style="text-align:right;">Backend daemon</td><td style="text-align:right;">Rust (tokio)</td><td style="text-align:right;">project state, file watching, process supervision of the kernels, the REPL and the agent sessions, the comm relay. Exposes a JSON line protocol to the frontend.</td></tr><tr><td style="text-align:right;">Julia kernel</td><td style="text-align:right;">Julia</td><td style="text-align:right;">the <code>FileType</code> dispatch table and Julia-aware previews, project scans (the Modules tree), the file content hash behind the drift check. Loads the project&#39;s <code>Project.toml</code> environment.</td></tr><tr><td style="text-align:right;">REPL</td><td style="text-align:right;">Julia</td><td style="text-align:right;">your interactive session, supervised by the backend, with a display shim that emits structured frames (stdout, stderr, value, image, error) over stdio.</td></tr></tbody></table><p>The frontend holds no project knowledge. The backend is the single owner of project state and the one protocol entry point. The Julia kernel is where every extensible, Julia-aware decision is made. The REPL is a separate process so a crash or a long computation in your interactive session never takes down the daemon that supervises it.</p><h2 id="Why-client/server,-even-on-one-machine" tabindex="-1">Why client/server, even on one machine <a class="header-anchor" href="#Why-client/server,-even-on-one-machine" aria-label="Permalink to &quot;Why client/server, even on one machine {#Why-client/server,-even-on-one-machine}&quot;">​</a></h2><p>The three processes communicate over a socket locally exactly as they would across a network. That looks like overhead on a single box, but it is the whole point: the same protocol serves local and remote; only the transport differs. The plumbing cost is paid once, up front, instead of being retrofitted later when local-only assumptions have already hardened.</p><p>This directly serves a requirement: local and remote operation must offer the <em>same</em> user experience. A design that special-cased &quot;local&quot; would have to grow a second path for &quot;remote&quot; and keep the two in sync forever. One socket-based protocol avoids that split entirely.</p><h2 id="Why-the-language-split" tabindex="-1">Why the language split <a class="header-anchor" href="#Why-the-language-split" aria-label="Permalink to &quot;Why the language split {#Why-the-language-split}&quot;">​</a></h2><p>The boundary between Rust and Julia is not arbitrary — each language does what it is best at.</p><p><strong>Rust is for plumbing.</strong> Rendering, IPC, file watching and process supervision all want a single statically-linked, cross-platform binary with predictable performance. <code>tokio</code>, <code>notify</code>, <code>winit</code>, and <code>wgpu</code> cover that stack. Keep this layer boring and predictable; it should rarely need to change when the feature set grows.</p><p><strong>Julia is for everything plugin-extensible and Julia-aware.</strong> <code>JuliaSyntax.jl</code> parses Julia source — reimplementing a Julia parser in Rust is a non-starter, and it is the parser the language itself uses. More fundamentally, the unique value proposition here is <em>multiple dispatch as the plugin mechanism</em>: a small set of abstract types whose methods are the extension ABI. That only works in Julia. See <a href="./../extend/abi">The Dispatch ABI</a>.</p><h2 id="The-serialization-seam" tabindex="-1">The serialization seam <a class="header-anchor" href="#The-serialization-seam" aria-label="Permalink to &quot;The serialization seam {#The-serialization-seam}&quot;">​</a></h2><p>The Rust↔Julia boundary is crossed by exactly two generic structs, both carrying <strong>opaque, kernel-defined payloads</strong>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TreeNode</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # opaque to Rust</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    label</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    kind</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Symbol</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # :module, :function, :pngfile, ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    has_children</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Bool</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    badges</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Vector{Symbol}</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # design of the unbuilt per-entity layer: :stale, :user_edited, :immutable, ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    payload</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dict{String,Any}</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # opaque, kernel-defined per kind</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PreviewPayload</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    mime</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Vector{UInt8}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    extras</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dict{String,Any}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>Of the two, <code>PreviewPayload</code> is built (file-type previews return it). Core&#39;s Julia <code>TreeNode</code> is declared but not built: no Julia code constructs one today. The window&#39;s trees are built by the daemon and from the kernel&#39;s project scan, and travel as the Rust wire type <code>TreeNode</code> with the same fields.</p><p>The frontend draws whatever tree the kernel sends and dispatches on <code>PreviewPayload</code>&#39;s <code>mime</code> to pick a renderer. It never inspects <code>id</code> or <code>payload</code>; it never learns what a <code>:pngfile</code> <em>is</em>. The consequence is the load-bearing property of the whole design: <strong>adding a new <code>FileType</code> needs no Rust change</strong> unless its output must be bounded, in which case the daemon&#39;s preview gates also name its extensions (<code>Mode</code> is not built: the modes are native Rust views today). A plugin that teaches the kernel to preview a new file format ships entirely in Julia, and the frontend renders it because the MIME type tells it how. See <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.TreeNode"><code>TreeNode</code></a> and <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.PreviewPayload"><code>PreviewPayload</code></a> in the API reference.</p><h2 id="Deployment-topology" tabindex="-1">Deployment topology <a class="header-anchor" href="#Deployment-topology" aria-label="Permalink to &quot;Deployment topology {#Deployment-topology}&quot;">​</a></h2><p>The architecture&#39;s payoff shows up in the standard remote deployment: a Windows or local frontend driving a Linux backend where the Julia kernel and GPU live.</p><ul><li><p>The <strong>backend runs as a long-lived daemon on the remote</strong> — the <code>systemd --user</code> unit <code>sotd.service</code> — so it survives SSH disconnects.</p></li><li><p>It listens on a <strong>per-session Unix socket</strong>, not a host-allocated TCP port.</p></li><li><p>The <strong>frontend spawns its own <code>ssh</code> child</strong> running <code>sotd stdio-bridge</code> on the remote and speaks the same JSON line protocol over its stdin/stdout — no forward, no local port. See <a href="./../concepts/transport">Transport</a>.</p></li><li><p>On reconnect (after a laptop sleep, a wifi flap, or a fresh client), the frontend re-attaches by <strong>session id</strong>; the kernel keeps its state — variables, loaded modules, in-flight computations — across the gap.</p></li></ul><p>A single daemon can host <strong>one Julia kernel per workspace</strong>, routed by <code>workspace_id</code>, so switching the active project is fast and never tears the kernel down. Each agent session runs in its own <strong>capsule</strong> supervisor, which the daemon starts and lists but does not hold up, so sessions survive frontend relaunches and daemon restarts alike (closing the window ends this computer&#39;s sessions; see ADR 0050) — see <a href="./../concepts/sessions">Sessions and persistence</a>.</p><p>On Linux the daemon runs as the child of a small guard process, which is the process the launcher or the unit starts. The kernel, the REPL, Pluto and every other process the daemon starts, at any depth and however they detach, end within a few seconds of the daemon&#39;s end, even when the daemon is killed; a capsule does not, by design. A crashed Pluto server can leave one Julia worker per open notebook, which ends when the daemon ends. The guard exits with the daemon&#39;s own status. A process a broker starts, the loss of the guard itself and a process stuck in an uninterruptible kernel call are outside it, and macOS has no guard: only a controlled end of the daemon ends its children there, and not a process that left a child&#39;s process group, such as Pluto&#39;s notebook worker (ADR 0050).</p><h2 id="Where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#Where-to-go-next" aria-label="Permalink to &quot;Where to go next {#Where-to-go-next}&quot;">​</a></h2><ul><li><p><a href="./modes">Modes</a> — the switchable nav-tree roots over the same code.</p></li><li><p><a href="./previews">Previews</a> — which file types render, and at what fidelity.</p></li><li><p><a href="./../extend/abi">The Dispatch ABI</a> — how multiple dispatch is the plugin system.</p></li><li><p><a href="./../design/rendering">Frontend Rendering</a> — how previews are drawn into the window.</p></li><li><p><a href="./../design/backend">Backend &amp; Sessions</a> — daemon internals and session lifecycle.</p></li><li><p><a href="./../design/protocol">The Line Protocol</a> — the JSON wire format between the processes.</p></li></ul>`,25)])])}const k=t(o,[["render",r]]);export{g as __pageData,k as default};
